/* Help popup */

function popUp(URL) {
	day = new Date();
	id = day.getTime();
	window.open(URL, '" + id + "', 'toolbar=0,scrollbars=1,location=0,statusbar=0,menubar=0,resizable=1,width=800,height=300,left=540,top=250');
	//eval("page" + id + " = window.open(URL, '" + id + "', 'toolbar=0,scrollbars=1,location=0,statusbar=0,menubar=0,resizable=1,width=800,height=300,left=540,top=250');");
}

/* Form validation */

function validate_required(field,alerttxt)
{
with (field) {
  if (value==null||value=="") {
    alert(alerttxt);return false;
  }
  else {
    return true;
  }
 }
}

function validateGuestbookForm(thisform) {
with (thisform) {

  // Guestbook form
  if (validate_required(txtName,"Name can not be empty.")==false)
  {txtName.focus();return false;}
  
  if (validate_required(mtxMessage,"Message can not be empty.")==false)
  {mtxMessage.focus();return false;}
  
  }
}

function confirmClearGuestbook() {
	return confirm("Are you sure you want to clear the guestbook?");
}

function toggleTheme() {
    document.body.classList.toggle('dark');
    const theme = document.body.classList.contains('dark') ? 'dark' : 'light';
    document.cookie = "theme=" + theme + "; path=/";
}

// These functions need to be called after the content they reference
// has been added to the page otherwise they will fail.

function addEventListeners() {
	var source_button = document.getElementById ("source_button");

	if (source_button) {
		source_button.addEventListener("click", function() {
			var url=source_button.dataset.sourceUrl;
			popUp (url);
		});
	}

	var help_button = document.getElementById ("help_button");

	if (help_button) {
		help_button.addEventListener("click", function() {
			var url=help_button.dataset.helpUrl;
			popUp (url);
		});
	}
}

addEventListeners();

function show_save_result (data) {
	if (data.result == 'ok') {
		document.getElementById('save_result').innerText = 'Save Successful';
	} else {
		document.getElementById('save_result').innerText = 'Save Failed';
	}
}

function submit_change(id) {
	first_name = document.getElementById('first_name_' + id).value
	surname = document.getElementById('surname_' + id).value

	fetch('change_user_details.php', {
		method: 'POST',
		headers: {
			'Accept': 'application/json',
			'Content-Type': 'application/json'
		},
		body: JSON.stringify({ 'id': id, 'first_name': first_name, 'surname': surname })
	}
	)
	.then((response) => response.json())
	.then((data) => show_save_result(data));
}

function populate_form() {
	var xhr= new XMLHttpRequest();
	xhr.open('GET', 'get_user_data.php', true);
	xhr.onreadystatechange= function() {
		if (this.readyState!==4) {
			return;
		}
		if (this.status!==200) {
			return;
		}
		const users = JSON.parse (this.responseText);
		table_body = document.getElementById('user_table').getElementsByTagName('tbody')[0];
		users.forEach(updateTable);

		function updateTable (user) {
			var row = table_body.insertRow(0);
			var cell0 = row.insertCell(-1);
			cell0.innerHTML = user['user_id'] + '<input type="hidden" id="user_id_' + user['user_id'] + '" name="user_id" value="' + user['user_id'] + '" />';
			var cell1 = row.insertCell(1);
			cell1.innerHTML = '<input type="text" id="first_name_' + user['user_id'] + '" name="first_name" value="' + user['first_name'] + '" />';
			var cell2 = row.insertCell(2);
			cell2.innerHTML = '<input type="text" id="surname_' + user['user_id'] + '" name="surname" value="' + user['surname'] + '" />';
			var cell3 = row.insertCell(3);
			cell3.innerHTML = '<input type="button" value="Update" onclick="submit_change(' + user['user_id'] + ')" />';
		}
	};
	xhr.send();
}

body {
	margin: 0;
	color: #2f2f2f;
	font: 12px/15px Arial, Helvetica, sans-serif;
	min-width: 981px;
	height: 100%;
	position: relative;
}

body.home {
	background: #e7e7e7;
}

div.clear {
	clear: both;
}

a {
	color: #99cc33;
	text-decoration: underline;
	font-weight: bold;
}

a img {
	border: 0;
}

a: hover {
	text-decoration: none;
}

input, textarea, select {
	font: 100% arial,sans-serif;
	vertical-align: middle;
}

form,fieldset {
	margin: 0;
	padding: 0;
	border-style: none;
}

em {
	font-weight: bold;
	font-style: normal;
}

h1, h2, h3, h4, h5, h6 {
	margin-top: 0px;
}

h1 {
	font-size: 200%;
}

h2 {
	font-size: 160%;
}


h3 {
	font-size: 130%;
}

hr {
	border-width: 0px;
	color: #C3D9FF;
	background-color: #C3D9FF;
	height: 1px;
}

ul.menuBlocks {
	list-style-type: none;
	padding-left: 0px;
	margin-top: 0px;
	margin-bottom: 0px;
	margin-left: 0px;
}

ul + ul, ul + ul.menuBlocks, ul + h1, ul + h2, ul + p {
	margin-top: 20px;
}

.fixed {
	font-family: Fixed, Courier, monospace;
	font-size: 13px;
}

div.nearly {
	border: 2px solid #0000ff;
	padding: 10px 20px 10px 20px;
	margin-top: 15px;
	margin-bottom: 15px;
}

div.success {
	border: 2px solid #00ff00;
	padding: 10px 20px 10px 20px;
	text-align: center;
	font-weight: bold;
	margin-top: 15px;
	margin-bottom: 15px;
}

div.warning {
	border: 2px solid #ff0000;
	padding: 10px 20px 10px 20px;
	color: #800000;
	margin-top: 15px;
	margin-bottom: 15px;
}

div.warning h1 {
	color: #ff0000;
}

div.message {
	border: 1px solid #C0C0C0;
	padding: 5px;
	margin: 10px 0px 10px 0px;
	background-color: #f8fafa;
	width: 45%;
}

div#container {
	width: 900px;
	height: 100%;
	margin-left: auto;
	margin-right: auto;
	background: #f4f4f4;
	font-size: 13px;
}

div#header {
	position: relative;
	padding: 10px;
	overflow: hidden;
	background: #2f2f2f;
	border-bottom: 5px solid #A1CC33;
	text-align: center;
}

div#system_info {
	padding: 10px;
	text-align: right;
}

div#main_body {
	float: right;
	width: 693px;
	background: #f4f4f4;
	padding-top: 20px;
	padding-bottom: 10px;
	font-size: 13px;
}

div.body_padded {
	padding-left: 20px;
	padding-right: 20px;
}

div#main_menu {
	float: left;
	width: 200px;
	height: 100%;
	background-color: #f4f4f4;
	padding-top: 10px;
	padding-bottom: 10px;
}

div#main_menu li {
	border-width: 1px;
	border-style: solid;
	border-color: #D2D4D4 #6B778C #6B778C #D2D4D4;
	padding: 3px 5px 3px 5px;
	margin-bottom: 3px;
	background-color: #bebebe;
}

div#main_menu li a {
	color: #000000;
	text-decoration: none;
	display: block;
}

div#main_menu li:hover {
    background-color: #ccc;
}


div#main_menu li.selected {
	border-color: #758DAE #758DAE #758DAE #758DAE;
	background-color: #99cc33;
}

div#main_menu li.selected a {
	color: #F9F7ED;
}

div#main_menu li: hover {
	border-color: #D2D4D4;
}

div#main_menu li: hover a {
	color: #F9F7ED;
}

div#main_menu_padded {
	padding: 15px;
}

div#footer {
	color: #999999;
	background: #2f2f2f;
	padding: 10px;
	text-align: center;
	border-top: 5px solid #A1CC33;
}

.popup_button {
    border-width: 1px;
    border-style: solid;
    border-color: #D2D4D4 #6B778C #6B778C #D2D4D4;
    padding: 3px 5px;
    margin-bottom: 3px;
    background-color: #bebebe;
    font-weight: bold;
    float: right;
    cursor: pointer;
    color: #000000;
}

.popup_button:hover {
	color: white;
    background-color: #A1CC33;
}




div.vulnerable_code_area {
	background-color: #f8fafa;
	border-width: 1px;
	border-style: solid;
	border-color: #000000;
	padding: 10px 20px 10px 20px;
	margin-bottom: 20px;
}

div#guestbook_comments {
	width: 45%;
	background-color: #f8fafa;
	border-width: 1px;
	border-style: solid;
	border-color: #C0C0C0;
	padding: 5px 10px 5px 10px;
	margin-bottom: 5px;
}

